// Builds the MasalaPOS Cafe debug APK (apps/cafe-android). Release signing comes in Phase 5.
//
//   node tools/build-cafe-android.mjs            prebuild the native project and assemble a debug APK
//   node tools/build-cafe-android.mjs --install  also install it on the phone attached over USB (adb install -r)
//
// The android/ folder is generated by `expo prebuild` from app.json and is never committed.
import { spawnSync } from "node:child_process";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const app = join(root, "apps/cafe-android");
const windows = process.platform === "win32";

function javaHome() {
  const major = (home) => {
    try { return Number(/JAVA_VERSION="(\d+)/.exec(readFileSync(join(home, "release"), "utf8"))?.[1]); } catch { return 0; }
  };
  const candidates = [process.env.JAVA_HOME, windows ? "C:\\Program Files\\Android\\Android Studio\\jbr" : "/Applications/Android Studio.app/Contents/jbr/Contents/Home"].filter(Boolean);
  const found = candidates.find((home) => major(home) >= 17);
  if (!found) throw new Error("Android builds need JDK 17 or newer. Install Android Studio or set JAVA_HOME.");
  return found;
}

function sdkDir() {
  const sdk = process.env.ANDROID_HOME ?? process.env.ANDROID_SDK_ROOT ?? (windows ? join(process.env.LOCALAPPDATA ?? "", "Android", "Sdk") : join(homedir(), "Library/Android/sdk"));
  if (!existsSync(join(sdk, "platforms"))) throw new Error(`Android SDK not found at ${sdk}. Install it with Android Studio or set ANDROID_HOME.`);
  return sdk;
}

function run(command, args, options = {}) {
  const result = spawnSync(command, args, { stdio: "inherit", shell: windows && /\.(bat|cmd)$/.test(command), ...options });
  if (result.status !== 0) throw new Error(`${command} ${args.join(" ")} failed`);
}

const java = javaHome();
const sdk = sdkDir();
const env = { ...process.env, JAVA_HOME: java, ANDROID_HOME: sdk, EXPO_NO_GIT_STATUS: "1", CI: "1" };

run(windows ? "npx.cmd" : "npx", ["expo", "prebuild", "--platform", "android", "--no-install"], { cwd: app, env });
writeFileSync(join(app, "android", "local.properties"), `sdk.dir=${sdk.replaceAll("\\", "/")}\n`);
// cmd.exe runs the wrapper, so it is called by name from its folder. Phones and tablets are ARM, so the x86
// emulator ABIs are skipped, which halves the native build.
run(windows ? ".\\gradlew.bat" : "./gradlew", ["--console=plain", "-PreactNativeArchitectures=arm64-v8a,armeabi-v7a", "assembleDebug"],
  { cwd: join(app, "android"), env });

const apk = join(app, "android/app/build/outputs/apk/debug/app-debug.apk");
if (!existsSync(apk)) throw new Error(`Gradle finished but ${apk} is missing`);
console.log(`MasalaPOS Cafe debug APK: ${apk}`);

if (process.argv.includes("--install")) {
  const adb = join(sdk, "platform-tools", windows ? "adb.exe" : "adb");
  run(adb, ["install", "-r", apk]);
  console.log("Installed. For live reload: adb reverse tcp:8081 tcp:8081, then npm run dev:cafe");
}
